  function benchStrings(locale = "ru", labels2 = {}) {
    const base = STRINGS[locale === "ru" ? "ru" : "en"];
    const out = { ...base };
    for (const k of Object.keys(base)) {
      const label = labels2?.["bench" + k[0].toUpperCase() + k.slice(1)];
      if (typeof label === "string" && label) out[k] = label;
    }
    return out;
  }
  var fmt = (locale, x, digits = 1) => Number.isFinite(x) ? x.toLocaleString(locale === "ru" ? "ru-RU" : "en-US", {
    maximumFractionDigits: digits,
    minimumFractionDigits: 0
  }) : "\u2014";
  function settingsText(s, S) {
    const set = s.settings || {};
    return [
      set.graphics && S[set.graphics] || (set.economy ? S.economy : S.full),
      `${S.bloom} ${set.bloom ? "\u2713" : "\u2717"}`,
      set.reduced ? S.reduced : null,
      Number.isFinite(set.pixelRatio) ? `\xD7${set.pixelRatio.toFixed(2)}` : null
    ].filter(Boolean).join(", ");
  }
  function formatSummary(result, S, locale = "ru") {
    const r = result.stats, s = result.specs, f = (x, d) => fmt(locale, x, d), lines = [
      `${S.title} \u2014 ${S[result.scene] || result.scene}`,
      `${f(r.score, 0)} ${S.score}`,
      `${S.avgFps}: ${f(r.avgFps)} \xB7 ${S.low1}: ${f(r.low1Fps)} \xB7 ${S.low01}: ${f(r.low01Fps)}`,
      `${S.median}/p95/p99: ${f(r.frameMs.median, 2)} / ${f(r.frameMs.p95, 2)} / ${f(r.frameMs.p99, 2)} ${S.ms}`,
      `${S.cpu}: ${f(r.cpuMs.avg, 2)} ${S.ms} (p95 ${f(r.cpuMs.p95, 2)})`,
      `${S.gpu}: ${r.gpuMs ? `${f(r.gpuMs.avg, 2)} ${S.ms} (p95 ${f(r.gpuMs.p95, 2)})` : S.na}`,
      `${S.draws}: ${f(r.calls.avg, 0)} ${S.avg} / ${f(r.calls.max, 0)} ${S.max} \xB7 ${S.tris}: ${f(r.triangles.avg / 1e3, 0)}K / ${f(r.triangles.max / 1e3, 0)}K`,
      result.heapMb ? `${S.heap}: ${f(result.heapMb, 0)} ${S.mb}` : null,
      s.firstFrameMs ? `${S.load}: ${f(s.firstFrameMs / 1e3, 2)} ${S.s}` : null,
      `${S.gpuName}: ${s.gpu || "\u2014"}`,
      `${S.cores}: ${s.cores ?? "\u2014"} \xB7 ${S.memory}: ${s.memory ? s.memory + " " + S.gb : "\u2014"}`,
      `${S.screen}: ${s.screen || "\u2014"} \xB7 ${S.canvas}: ${s.canvas || "\u2014"} \xB7 DPR ${s.dpr ?? "\u2014"} \xB7 ${S.refresh}: ${s.refresh ? s.refresh + " " + S.hz : "\u2014"}`,
      `${S.browser}: ${s.browser || "\u2014"} \xB7 ${S.os}: ${s.os || "\u2014"}`,
      `${S.quality}: ${settingsText(s, S)} \xB7 ${s.webgl || "\u2014"}`,
      `${S.build}: ${s.build || "\u2014"} \xB7 ${S.projects}: ${s.projects ?? "\u2014"} \xB7 ${new Date(result.at).toISOString().slice(0, 16).replace("T", " ")}`,
      result.resized ? S.resized : null
    ];
    return lines.filter(Boolean).join("\n");
  }
